import { describe, expect, it } from 'vitest';
import { TEAM_EMOJI_IDS } from './team-emojis';

/**
 * `team-emojis.ts` is generated by `scripts/build-team-emojis.ts`, so this checks
 * the shape of what the script writes rather than the ids themselves. A typo in a
 * hand-edited map would not fail a card test — it would silently drop that team's
 * mark from every card — which is why the invariant is pinned here.
 */
describe('TEAM_EMOJI_IDS', () => {
  const TRICODES = [
    'ATL',
    'BKN',
    'BOS',
    'CHA',
    'CHI',
    'CLE',
    'DAL',
    'DEN',
    'DET',
    'GSW',
    'HOU',
    'IND',
    'LAC',
    'LAL',
    'MEM',
    'MIA',
    'MIL',
    'MIN',
    'NOP',
    'NYK',
    'OKC',
    'ORL',
    'PHI',
    'PHX',
    'POR',
    'SAC',
    'SAS',
    'TOR',
    'UTA',
    'WAS',
  ];

  it('covers all 30 teams', () => {
    expect(Object.keys(TEAM_EMOJI_IDS).sort()).toEqual(TRICODES);
  });

  it('holds a Discord snowflake or null for every team', () => {
    for (const [tricode, id] of Object.entries(TEAM_EMOJI_IDS)) {
      if (id === null) continue;
      // A snowflake is a decimal string; anything else would render as a broken
      // `<:TRICODE:id>` in every card.
      expect(id, `${tricode} must be a snowflake or null`).toMatch(/^\d{17,20}$/);
    }
  });

  it('never repeats an id, which would mean one team wearing another mark', () => {
    const ids = Object.values(TEAM_EMOJI_IDS).filter((id): id is string => id !== null);

    expect(new Set(ids).size).toBe(ids.length);
  });
});
